/**
 * This script runs `pnpm dlx @convex-dev/auth` to help with setting up
 * environment variables for Convex Auth.
 *
 * You can safely delete it and remove it from package.json scripts.
 */

import fs from "fs";
import { config as loadEnvFile } from "dotenv";
import { spawnSync } from "child_process";

if (!fs.existsSync(".env.local")) {
  // Something is off, skip the script.
  process.exit(0);
}

const config = {};
loadEnvFile({ path: ".env.local", processEnv: config, quiet: true });

const runOnceWorkflow = process.argv.includes("--once");

if (runOnceWorkflow && config.SETUP_SCRIPT_RAN !== undefined) {
  // The script has already ran once, skip.
  process.exit(0);
}

const result = spawnSync(
  "pnpm",
  ["dlx", "@convex-dev/auth", "--skip-git-check"],
  {
    stdio: "inherit",
  },
);

if (runOnceWorkflow && result.status === 0) {
  fs.writeFileSync(".env.local", `\nSETUP_SCRIPT_RAN=1\n`, { flag: "a" });
}

process.exit(result.status);

import { useEffect, useState } from "react";
import { Shell } from "@/components/Shell";
import Landing from "@/pages/Landing";
import Auth from "@/pages/Auth";
import Timeline from "@/pages/Timeline";
import EventPage from "@/pages/Event";
import NewEvent from "@/pages/NewEvent";
import Settings from "@/pages/Settings";

// ponytail: hash router in 10 lines; swap for react-router when nested routes appear
function useHash() {
  const [hash, setHash] = useState(window.location.hash);
  useEffect(() => {
    const onChange = () => setHash(window.location.hash);
    window.addEventListener("hashchange", onChange);
    return () => window.removeEventListener("hashchange", onChange);
  }, []);
  return hash.replace(/^#\/?/, "");
}

export default function App() {
  const route = useHash();
  const [path, param] = route.split("/");

  if (path === "") return <Landing />;
  if (path === "signin") return <Auth mode="signIn" />;
  if (path === "signup") return <Auth mode="signUp" />;

  return (
    <Shell>
      {path === "timeline" && <Timeline />}
      {path === "event" && <EventPage id={param} />}
      {path === "new" && <NewEvent />}
      {path === "settings" && <Settings />}
    </Shell>
  );
}

